<template>
  <div class="activity-detail">
    <title-line :title="title" />
    <img :src="acturl" alt="" style="width:100%" @click="goTaskCenter($event)">
    <van-popup v-model="showService">
      <customer-service @close="showService=false" />
    </van-popup>
  </div>
</template>
<script>
import CustomerService from '../portal/modules/CustomerService.vue'
import TitleLine from '../portal/modules/TitleLine'
import { getActinfo } from '@/api/activity.js'
export default {
  components: {
    TitleLine,
    CustomerService
  },
  data() {
    return {
      showService: false,
      title: '活动详情',
      taskList: [],
      maxmons: '',
      infos: '',
      acturl: '', // https://imgrr666.net/imgnew/activity-yueka.png
      monsList: [],
      telgramurl: 'https://t.me/rryl666'
    }
  },
  async created() {
    // this.initActinfo()
  },
  mounted() {
    this.acturl = this.$route.query.url
  },
  methods: {
    initActinfo() {
      getActinfo({ actcode: 'actUserfirstSupple' }).then(res => {
        this.maxmons = res.maxmons
        this.infos = res.infos
        this.monsList = res.datalist
        this.acturl = res.acturl
      })
    },
    openNew() {
      this.showService = true
      // window.open(this.telgramurl)
    },
    goTaskCenter(e) {
      if (this.$route.query.actcode === 'newsc' ||this.$route.query.actcode === 'yesczmonssong' || this.$route.query.actcode === 'allbuysong1' || this.$route.query.actcode === 'actSupplEeverytime' || this.$route.query.actcode === 'actDayFirstSupple' || this.$route.query.actcode === 'actNewercharge') {
        this.$router.push({ path: '/hwrecharge' })
      } else if (this.$route.query.actcode === 'actvipzhoulijin') {
        this.$router.push({ path: '/home' })
      } else if (this.$route.query.actcode === 'zcrw' || this.$route.query.actcode === 'zbhd') {
        this.showService = true
      } else if (e.x > window.innerWidth / 2 || this.$route.query.actcode === 'monthka') {
        this.$router.push({ path: '/taskCenter', query: { actcode: this.$route.query.actcode }})
      } else if (e.x < window.innerWidth / 2) {
        if (localStorage.getItem('version') === 'new') {
          this.$router.push({ path: '/home', query: { actcode: this.$route.query.actcode }})
        } else {
          this.$router.push({ path: '/oldhome', query: { actcode: this.$route.query.actcode }})
        }
      }
    }
  }

}
</script>
<style lang="less" scoped>
.activity-detail {
    min-height: 100vh;
    width: 100%;
    // background: #19223b;
    background: url('~@/assets/portal/bg_内页普通背景.png') no-repeat 50%;
    background-size: 100% 100%;
    overflow: hidden;
    font-size: 24px;
    color: #fff;
    .bg{
        position: absolute;
        top: 0;
        left: 0;
        width: 100%;
        display: flex;
        justify-content: flex-start;
        align-items: flex-end;
        // background-image: url(~@/assets/portal/activity/activity-actUserfirstSupple-bg.jpg);
        background-size: 100% 100%;
        background-position: center center;
    }
}
</style>
